where slug = 'namae-port-skywalk' and activity_category = 'view' and description is not distinct from '남애항 방파제 입구, 조선 시대 양야도라 불린 섬의 봉수대 터에 세운 전망대예요. 계단을 조금만 오르면 닿아 아이와 가기에도 어렵지 않고, 2층으로 된 전망대 끝에서 항구와 바위에 부딪히는 파도, 언덕 위 해송을 내려다볼 수 있어요. 바닥 일부가 유리라 아래 바다가 살짝 비쳐요.';
update public.places set slug = 'yangyang-attraction-121', summary = '동해 어촌과 항구 풍경을 가까이에서 만날 수 있는 양양군의 동산항입니다.', address = '강원특별자치도  양양군  현남면  동산리  동산큰길 동산항교차로', latitude = 37.981091, longitude = 128.755767, image_url = null, image_credit = null, image_source_url = null, image_alt = null, activity_category = null, tags = '{}', description = null, price_summary = null, phone = null, verified_on = null
where slug = 'dongsan-port' and activity_category = 'nature' and description is not distinct from '파도가 잔잔하고 물이 얕은 작은 항구로, 봄이면 임연수와 도다리를 낚으러 오는 사람이 많고 배낚시도 이곳에서 나가요. 물이 맑아 스쿠버다이빙을 하러도 찾으며, 300m 길이의 방파제를 따라 걸으며 바다를 볼 수 있어요. 바로 옆 동산해변·죽도해변과 함께 둘러보기 좋아요.';
delete from public.places where id in ('20000000-0000-4000-8000-000000000302') and description is not distinct from '고성군이 2024년 8월 거진읍 반암리에 연 강원도 첫 반려동물 동반 해수욕장으로, 울타리를 친 모래밭에서 반려견이 목줄 없이 뛰고 바다에도 들어갈 수 있어요. 반려견 크기별로 구역을 나누고, 반려견 전용 온수 샤워장과 건조기를 갖췄어요. 같은 반암리의 일반 해수욕장인 반암해변과는 공간이 분리돼 있어, 개와 함께 바다를 즐기고 싶은 보호자에게 맞아요.';
delete from public.places where id in ('20000000-0000-4000-8000-000000000301') and description is not distinct from '공현진1리해변에서 북쪽으로 600m쯤 떨어진 공현진2리 마을 앞 해변으로, 고성군이 1리와 따로 관리하는 해수욕장이에요. 소나무 숲을 등진 백사장이 펼쳐지고 앞바다에 바위섬이 보이며, 가까운 공현진항에서 활어회와 방파제 낚시를 즐길 수 있어요.';
